import { createClient } from "@supabase/supabase-js";
import { Hono } from "hono";
import type { Database } from "../src/shared/database.types";
import {
  MAX_ADAPTER_NAME_LENGTH,
  WEBHOOK_TOKEN_PATTERN,
  type AdapterSignal,
} from "../src/shared/webhook";

// Env is generated by `pnpm cf-typegen` from wrangler.jsonc + .dev.vars.
const app = new Hono<{ Bindings: Env }>();

app.get("/api/health", (c) => c.json({ ok: true }));

// Timberborn HTTP Adapters call these when their input signal flips.
// The adapter's Method dropdown offers GET and POST, so accept both.
app.on(["GET", "POST"], "/hook/:token/:signal/:name", async (c) => {
  const { token, signal, name } = c.req.param();

  if (!WEBHOOK_TOKEN_PATTERN.test(token)) return c.notFound();
  if (signal !== "on" && signal !== "off") return c.notFound();
  if (!name || name.length > MAX_ADAPTER_NAME_LENGTH) {
    return c.json({ error: "invalid adapter name" }, 400);
  }

  const supabase = createClient<Database>(c.env.SUPABASE_URL, c.env.SUPABASE_SECRET_KEY, {
    auth: { persistSession: false, autoRefreshToken: false },
  });

  const { data: recorded, error } = await supabase.rpc("record_adapter_event", {
    p_token: token,
    p_adapter: name,
    p_state: (signal as AdapterSignal) === "on",
  });

  if (error) {
    console.error("record_adapter_event failed", error);
    return c.json({ error: "failed to record event" }, 500);
  }
  if (!recorded) return c.notFound();

  return c.body(null, 204);
});

app.all("/api/*", (c) => c.json({ error: "not found" }, 404));

export default app satisfies ExportedHandler<Env>;
